   World w=SessionProbe.view(activity);check(w.player==faction,"real source/faction29");World.Officer ruler=person(w,91);World.City city=w.city(ruler.cityId),port=w.city(20057);check(port!=null&&port.owner==-1,"strict actual neutral source port57 target");
   nav("地图");description("定位己方据点 "+city.name);text("出征");ListView roster=(ListView)tag("deploy.officers");invoke("showRosterTag",new Class<?>[]{ListView.class,String.class},roster,"deploy.role."+ruler.id);tap(tag("deploy.role."+ruler.id));await(v->("从编队移除 "+ruler.name).equals(v.getContentDescription()));tap(tag("deploy.tab.1"));description("剑兵 无需库存");quantity("兵力数量","5000");quantity("粮食数量","20000");tap(tag("deploy.confirm"));w=SessionProbe.view(activity);int unit=person(w,91).unitId;check(unit>=0,"normal army deployment");selectUnit(unit);pose(port.hex);
