   tap(tag("unit.attack-task"));tile(port.hex);text("确认任务");w=SessionProbe.view(activity);World.Unit u=w.unit(unit);check((u!=null&&u.march!=null&&u.march.intent==MarchOrders.Intent.ATTACK&&u.march.kind==MarchOrders.Kind.CITY&&u.march.targetId==port.id)||w.city(port.id).owner==faction,"actual confirmation commits explicit attack or immediate valid capture");shot("02-committed-attack-route");
